import { z } from "zod";

export const runtime = "nodejs";

const uuidSchema = z.string().uuid();

function formatDate(dateStr: string | null | undefined): string {
  if (!dateStr) return "-";
  try {
    return new Intl.DateTimeFormat("id-ID", {
      day: "numeric",
      month: "short",
      year: "numeric",
      timeZone: "Asia/Jakarta",
    }).format(new Date(dateStr));
  } catch {
    return dateStr;
  }
}

